import sys
sys.path.insert(0,'/opt/tools')
import rcb_dtb,numpy as np,mujoco
from scipy.spatial.transform import Rotation as Rot
class Controller:
 def __init__(self,s):
  self.s=s;self.m=s.model;self.d=mujoco.MjData(self.m);self.bid=self.m.body('palmleft_hand_C_MC').id
  self.jp=np.zeros((3,self.m.nv));self.jr=np.zeros((3,self.m.nv))
 def fk(self,q):
  self.d.qpos[:]=self.s.data.qpos;self.d.qpos[self.s._jq]=q;mujoco.mj_forward(self.m,self.d)
  return self.d.xpos[self.bid].copy(),self.d.xmat[self.bid].reshape(3,3).copy()
 def ik(self,pos,R,q=None,it=100):
  q=self.s.state()['q'].copy() if q is None else q.copy()
  for i in range(it):
   p,r=self.fk(q);err=np.r_[pos-p,Rot.from_matrix(R@r.T).as_rotvec()]
   if np.linalg.norm(err[:3])<2e-5 and np.linalg.norm(err[3:])<2e-4:break
   mujoco.mj_jacBody(self.m,self.d,self.jp,self.jr,self.bid)
   J=np.vstack([self.jp[:,:7],self.jr[:,:7]])
   dq=J.T@np.linalg.solve(J@J.T+.0001*np.eye(6),err)
   q[:7]=np.clip(q[:7]+dq*np.minimum(1,.12/(np.max(np.abs(dq))+1e-10)),self.s.lower[:7],self.s.upper[:7])
  return q
 def move(self,pos,R,hand=None,steps=120):
  q=self.s.targets.copy();p0,R0=self.fk(self.s.state()['q']);rv=Rot.from_matrix(R@R0.T).as_rotvec();h0=q[7:].copy()
  for i in range(steps):
   u=(i+1)/steps;u=u*u*(3-2*u)
   q=self.ik(p0+(pos-p0)*u,Rot.from_rotvec(rv*u).as_matrix()@R0,q,it=8)
   if hand is not None:q[7:]=h0+(hand-h0)*u
   self.s.step(q)
  return self.s.progress()
 def hold(self,n=60):
  for i in range(n): self.s.step(self.s.targets)
 def pads(self,q=None):
  q=self.s.state()['q'] if q is None else q
  p,R=self.fk(q)
  out={}
  for f in ['thumb','index','middle','ring','pinky']:
   g=self.m.geom('palmleft_'+f+'_elastomer').id
   out[f]=R.T@(self.d.geom_xpos[g]-p)
  return out
if __name__=='__main__':
 s=rcb_dtb.Session();c=Controller(s)
 print('true palm',c.fk(s.state()['q']))
 print('obj local',c.fk(s.state()['q'])[1].T@(s.state()['object_pos']-c.fk(s.state()['q'])[0]))
 for v in [0,.4,.8,1.2]:
  q=s.state()['q'];q[7:12]=[1.2,0,.6,0,.8]
  for k in [12,16,20,25]:q[k:k+4]=[v,0,1.3,1.0]
  print(v,c.pads(q))
 print('geomnames')
 for i in range(s.model.ngeom):
  if 'elastomer' in s.model.geom(i).name: print(i,s.model.geom(i).name,s.model.geom_pos[i])
